	ld hl, wMusCh1Timer
	ld a, [hl]
	and a
	jr z, .l401D
	dec [hl]
	ret
.l401D
	ld hl, wMusCh1Ptr
	ld a, [hl+]
	ld b, [hl]
	ld c, a

