; Note on: trigger, stop any drum, restart the pitch macro and the attack envelope.
MusCh1_NoteOn::
	ld hl, wMusCh1Update
	set 7, [hl]
	call MusCh1_DrumStop
	call MusCh1_PitchMacStart
	call MusCh1_EnvAttack
	ret

; Release: start the release envelope if there is one (once per note), else note off.
MusCh1_Release::
	ld a, [wMusCh1EnvRelease + 1]
	and a
	jr z, MusCh1_NoteOff
	ld a, [wMusCh1]
	bit 1, a
	jr z, MusCh1_NoteOff
	res 1, a
	ld [wMusCh1], a
	call MusCh1_EnvRelease
	ret
MusCh1_NoteOff::
	call MusCh1_EnvStop
	call MusCh1_PitchMacStop
	call MusCh1_Silence
	ret

; Silence: NRx2 = $01 (DAC off) unless the channel is muted.
