	call MusCh1_CalcPeriod
	ld hl, wMusCh1NRx4
	set 7, [hl]
	ld hl, wMusCh1Update
	ld a, [hl]
	or $1F
	ld [hl], a
	ld hl, wMusCh1
	set 1, [hl]
	ret
MusCh1_PrepPitch::
	call MusCh1_CalcPeriod
	ld hl, wMusCh1Update
	ld a, [hl]
	or $18
	ld [hl], a
	ret

; Period = PeriodTable[pitch>>3] + FineTuneTable[pitch], with PitchDetune before and Detune after.
