	ld hl, wMusCh1Pitch
	ld a, [hl+]
	ld e, a
	ld d, [hl]
	call MusCh1_AddPitchDetune
	call Music_PitchToPeriod
	call MusCh1_AddDetune
	ld hl, wMusCh1NRx4
	ld a, [hl]
	and $C0
	or d
	ld [hl-], a
	ld [hl], e
	ret
