MusCh1_DrumStop::
	xor a
	ld [wMusCh1DrumJp], a
	ret

; Drum n: point the RAM trampoline (jp) at DrumTable[n]. ch1 uses the table from entry 0,
; ch2-ch4 from entry 7.
MusCh1_DrumStart::
	ld a, [wMusCh1]
	bit 0, a
	ret nz
	ld h, $00
	add hl, hl
	ld de, DrumTable
	add hl, de
	call MusCh1_LoadDrum
	ld a, $C3
	ld [wMusCh1DrumJp], a
	ret

; Every frame: call the drum routine; it writes the registers itself and returns the next
; routine in de (0 = finished).
