	and a
	ret z
	ld a, [wMusCh1]
	bit 0, a
	ret nz
	call MusCh1_CallDrum
	ld a, e
	or d
	jr z, .l43A8
	ld hl, wMusCh1DrumPtr
	ld a, e
	ld [hl+], a
	ld [hl], d
	ret
