; Envelope step (every frame): $00 end; else NRx2 value (retrigger), then bytes with bit 7
; set (NRx1 length, enables the length counter), then a frame count.
MusCh1_EnvUpdate::
	ld a, [wMusCh1EnvPtr + 1]
	and a
	ret z
	ld a, [wMusCh1EnvTimer]
	and a
	jr z, .l446A
	dec a
	ld [wMusCh1EnvTimer], a
	ret
