	ld hl, wMusCh1EnvPtr
	ld a, [hl+]
	ld b, [hl]
	ld c, a
	call MusCh1_EnvFetch
	ld a, e
	inc bc
	and a
	jr z, .l44B2
	ld [wMusCh1NRx2], a
	ld hl, wMusCh1Update
	ld e, a
	ld a, [hl]
	or $1F
	ld [hl], a
	ld a, e
	ld hl, wMusCh1NRx4
	res 6, [hl]
	set 7, [hl]
.l448B
	call MusCh1_EnvFetch
	ld a, e
	inc bc
	bit 7, a
	jr z, .l44A7
	and $3F
	ld e, a
	ld a, [wMusCh1NRx1]
	and $C0
	or e
	ld [wMusCh1NRx1], a
	ld hl, wMusCh1NRx4
	set 6, [hl]
	jr .l448B
.l44A7
	dec a
	ld [wMusCh1EnvTimer], a
	ld hl, wMusCh1EnvPtr
	ld a, c
	ld [hl+], a
	ld [hl], b
.l44B1
	ret
.l44B2
