	ld [wMusCh1EnvPtr + 1], a
	jr .l44B1

; SLIDE: move the pitch by SlideStep per tick, landing exactly on the target on the last tick.
MusCh1_SlideUpdate::
	ld a, [wMusCh1SlideTimer]
	and a
	ret z
	ld hl, wMusCh1Update
	set 6, [hl]
	dec a
	ld [wMusCh1SlideTimer], a
	and a
	jr z, .l450F
	ld hl, wMusCh1SlideStep
	ld a, [hl+]
	ld c, a
	ld b, [hl]
	bit 7, b
	jr nz, .l44F1
	ld hl, wMusCh1SlideLeft
	ld a, [hl]
	sub c
	ld [hl+], a
	ld a, [hl]
	sbc a, b
	ld [hl+], a
	ld a, [hl]
	sbc a, $00
	ld [hl+], a
	ld de, wMusCh1SlideFrac
	ld hl, wMusCh1Pitch
	ld a, [de]
	add a, c
	ld [de], a
	ld a, [hl]
	adc a, b
	ld [hl+], a
	ld a, [hl]
	adc a, $00
	ld [hl+], a
	ret
.l44F1
	ld hl, wMusCh1SlideLeft
	ld a, [hl]
	sub c
	ld [hl+], a
	ld a, [hl]
	sbc a, b
	ld [hl+], a
	ld a, [hl]
	sbc a, $FF
	ld [hl+], a
	ld de, wMusCh1SlideFrac
	ld hl, wMusCh1Pitch
	ld a, [de]
	add a, c
	ld [de], a
	ld a, [hl]
	adc a, b
	ld [hl+], a
	ld a, [hl]
	adc a, $FF
	ld [hl+], a
