; Music_Init: clear $C5F0-$C6CD, reset the APU (NR52 off/on), NR50 $77, NR51 $FF, silence.
Music_Init::
	push bc
	push hl
	ld hl, wMusicFlags
	xor a
	ld bc, $00DE
	inc b
	inc c
.l538E
	ld [hl+], a
	dec c
	jr nz, .l538E
	dec b
	jr nz, .l538E
	ld a, $00
	ldh [rNR52], a
	ld [wMusicNR52], a
	ld a, $80
	ldh [rNR52], a
	ld [wMusicNR52], a
	ld a, $77
	ldh [rNR50], a
	ld [wMusicNR50], a
	ld a, $FF
	ldh [rNR51], a
	ld [wMusicPan], a
	ld [wMusicNR51], a
	call Music_SilenceAll
	pop hl
	pop bc
	ret

; Music_Play: l = song. Keeps the channel mute bits, re-inits, loads the 4 track pointers.
Music_Play::
	push bc
	push de
	ld a, [wMusCh1]
	and $01
	push af
	ld a, [wMusCh2Flags]
	and $01
	push af
	ld a, [wMusCh3Flags]
	and $01
	push af
	ld a, [wMusCh4Flags]
	and $01
	push af
	call Music_Init
	pop af
	ld [wMusCh4Flags], a
	pop af
	ld [wMusCh3Flags], a
	pop af
	ld [wMusCh2Flags], a
	pop af
	ld [wMusCh1], a
	ld e, l
	xor a
	ld h, a
	ld d, a
	add hl, hl
	add hl, de
	ld de, SongTable + 2
	add hl, de
	call Music_GetSongHeader
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh1Ptr], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh1Ptr + 1], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh2Ptr], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh2Ptr + 1], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh3Ptr], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh3Ptr + 1], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh4Ptr], a
	call Music_FetchHeaderByte
	ld a, e
	ld [wMusCh4Ptr + 1], a
	ld hl, wMusicFlags
	set 7, [hl]
	ld a, $06
	ld [wMusicTempo], a
	ld a, $1E
	ld [wMusicTempoAcc], a
	pop de
	pop bc
	ret
