; Music_Update: tempo accumulator (ticks per frame = wMusicTempo/30). On tick frames:
; tracks, pitch macros, slides. Every frame: envelopes, drums, fade, register writes.
Music_Update::
	ld hl, wMusicFlags
	bit 7, [hl]
	jp z, .l5520
	ld a, [wMusicTempo]
	ld b, a
	ld a, [wMusicTempoAcc]
	sub b
	jr z, .l54D9
	jr nc, .l54FF
.l54D9
	add a, $1E
	ld [wMusicTempoAcc], a
	call MusCh1_Update
	call MusCh2_Update
	call MusCh3_Update
	call MusCh4_Update
	call MusCh1_PitchMacUpdate
	call MusCh2_PitchMacUpdate
	call MusCh3_PitchMacUpdate
	call MusCh1_SlideUpdate
	call MusCh2_SlideUpdate
	call MusCh3_SlideUpdate
	jp .l5502
.l54FF
	ld [wMusicTempoAcc], a
.l5502
	call MusCh1_EnvUpdate
	call MusCh2_EnvUpdate
	call MusCh3_EnvUpdate
	call MusCh4_EnvUpdate
	call MusCh1_DrumUpdate
	call MusCh2_DrumUpdate
	call MusCh3_DrumUpdate
	call MusCh4_DrumUpdate
	call Music_FadeUpdate
	call Music_WriteRegs
.l5520
	ret

