; Fade: every wFadeSpeed frames take the next step of FadeStepTable.
Music_FadeUpdate::
	ld a, [wFadeSpeed]
	and a
	ret z
	ld hl, wFadeTimer
	ld a, [hl]
	and a
	jr z, .l571F
	dec [hl]
	ret
.l571F
	ld a, [wFadeSpeed]
	dec a
	ld [wFadeTimer], a
	ld a, [wFadeStep]
	add a, a
	ld l, a
	ld h, $00
	ld bc, FadeStepTable
	add hl, bc
	ld a, [hl+]
	ld h, [hl]
	ld l, a
	jp hl

; 7 x NR50 volume -1, NR50 = 0, stop the channels, one idle step, music off.
FadeStepTable::
	dw Fade_VolumeDown  ; step 0
	dw Fade_VolumeDown  ; step 1
	dw Fade_VolumeDown  ; step 2
	dw Fade_VolumeDown  ; step 3
	dw Fade_VolumeDown  ; step 4
	dw Fade_VolumeDown  ; step 5
	dw Fade_VolumeDown  ; step 6
	dw Fade_KeepTopBits  ; step 7
	dw Fade_StopChannels  ; step 8
	dw B20_57C0  ; step 9
	dw Fade_Done  ; step 10
Fade_Done::
	xor a
	ld [wFadeSpeed], a
	ld [wFadeTimer], a
	ld [wFadeStep], a
	ld hl, wMusicFlags
	res 7, [hl]
	ret
