; de = pitch -> de = period (PeriodTable + FineTuneTable).
Music_PitchToPeriod::
	ld hl, FineTuneTable
	add hl, de
	ld c, [hl]
	srl d
	rr e
	srl d
	rr e
	res 0, e
	ld hl, PeriodTable
	add hl, de
	ld a, [hl+]
	add a, c
	ld e, a
	ld d, [hl]
	jr nc, .l5856
	inc d
.l5856
	ret

